import dotenv from "dotenv";
import { MongoClient } from "mongodb";

dotenv.config();

function redact(text) {
  if (!text) return "";
  return String(text)
    .replace(/mongodb(\+srv)?:\/\/[^@]+@/gi, "mongodb+srv://<redacted>:<redacted>@")
    .replace(/:([^:@]+)@/g, ":<redacted>@");
}

async function runDiagnosis() {
  const uri = process.env.MONGODB_URI;
  if (!uri) {
    console.log("DIAGNOSTIC: MONGODB_URI is not set in environment or .env file.");
    return;
  }

  console.log(`DIAGNOSTIC_URI: ${redact(uri)}`);

  let client;
  try {
    console.log("DIAGNOSTIC: Initializing MongoClient...");
    client = new MongoClient(uri, {
      serverSelectionTimeoutMS: 5000,
      connectTimeoutMS: 5000,
      appName: "keys-of-the-departed-diag",
    });

    console.log("DIAGNOSTIC: Attempting MongoClient.connect()...");
    await client.connect();
    console.log("DIAGNOSTIC_CONNECTION: SUCCESS");

    const dbName = process.env.MONGODB_DB_NAME || "keys_departed";
    const db = client.db(dbName);

    console.log(`DIAGNOSTIC: Pinging database '${dbName}'...`);
    const pingResult = await db.command({ ping: 1 });
    console.log(`DIAGNOSTIC_PING: SUCCESS (${JSON.stringify(pingResult)})`);

    console.log("DIAGNOSTIC: Listing collection names only...");
    const collections = await db.listCollections().toArray();
    const names = collections.map((c) => c.name);
    console.log(`DIAGNOSTIC_COLLECTIONS: ${JSON.stringify(names)}`);
  } catch (err) {
    console.error("DIAGNOSTIC_CONNECTION: FAILED");
    const sanitizedMsg = redact(err.message || String(err));
    console.error(`DIAGNOSTIC_ERROR_NAME: ${err.name}`);
    console.error(`DIAGNOSTIC_ERROR_CODE: ${err.code || "N/A"}`);
    console.error(`DIAGNOSTIC_ERROR_MESSAGE: ${sanitizedMsg}`);
    if (err.cause) {
      console.error(`DIAGNOSTIC_ERROR_CAUSE: ${redact(err.cause.message || String(err.cause))}`);
    }
    if (err.reason) {
      console.error(`DIAGNOSTIC_ERROR_REASON: ${redact(JSON.stringify(err.reason))}`);
    }
  } finally {
    if (client) {
      await client.close();
      console.log("DIAGNOSTIC: Client closed.");
    }
  }
}

runDiagnosis().catch((err) => {
  console.error("FATAL_DIAG_ERROR:", redact(err.message));
});

