import dotenv from "dotenv";
import path from "path";
import { fileURLToPath } from "url";
import { MongoClient } from "mongodb";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
dotenv.config({ path: path.join(__dirname, ".env") });

function redact(text) {
  if (!text) return "";
  return String(text)
    .replace(/mongodb(\+srv)?:\/\/[^@]+@/gi, "mongodb+srv://<redacted>:<redacted>@")
    .replace(/:([^:@]+)@/g, ":<redacted>@");
}

async function runDiagnosis() {
  const uri = process.env.MONGODB_URI;
  if (!uri) {
    console.error("DIAGNOSTIC_ERROR: MONGODB_URI is not set in environment or server/.env file.");
    return;
  }

  let client;
  try {
    console.log("DIAGNOSTIC_STEP: Connecting via MongoClient.connect()...");
    client = new MongoClient(uri, {
      serverSelectionTimeoutMS: 5000,
      connectTimeoutMS: 5000,
      appName: "keys-of-the-departed-diag",
    });

    await client.connect();
    console.log("DIAGNOSTIC_CONNECT: SUCCESS");

    const dbName = process.env.MONGODB_DB_NAME || "keys_departed";
    const db = client.db(dbName);

    console.log(`DIAGNOSTIC_STEP: Executing db.command({ ping: 1 }) on database '${dbName}'...`);
    const pingResult = await db.command({ ping: 1 });
    console.log(`DIAGNOSTIC_PING_RESULT: ${JSON.stringify(pingResult)}`);

    console.log("DIAGNOSTIC_STEP: Listing collection names only...");
    const collections = await db.listCollections().toArray();
    const collectionNames = collections.map((c) => c.name);
    console.log(`DIAGNOSTIC_COLLECTIONS: ${JSON.stringify(collectionNames)}`);

    console.log("DIAGNOSTIC_STEP: Checking MongoInvestigationsRepository selection...");
    const { MongoInvestigationsRepository } = await import("./src/repositories/mongoInvestigationsRepository.js");
    const investigationsRepo = new MongoInvestigationsRepository(db);

    const isInstance = investigationsRepo instanceof MongoInvestigationsRepository;
    const hasRequiredMethods =
      typeof investigationsRepo.createInvestigation === "function" &&
      typeof investigationsRepo.listInvestigations === "function" &&
      typeof investigationsRepo.findInvestigationById === "function";

    console.log(`DIAGNOSTIC_REPO_INSTANCE_OF_MONGO: ${isInstance}`);
    console.log(`DIAGNOSTIC_REPO_HAS_METHODS: ${hasRequiredMethods}`);
    console.log("DIAGNOSTIC_REPO_SELECTION: SUCCESS - MongoInvestigationsRepository successfully selected and instantiated.");
  } catch (err) {
    console.error("DIAGNOSTIC_STATUS: FAILED");
    const sanitizedMsg = redact(err.message || String(err));
    console.error(`DIAGNOSTIC_ERROR_NAME: ${err.name}`);
    console.error(`DIAGNOSTIC_ERROR_MESSAGE: ${sanitizedMsg}`);
    if (err.cause) {
      console.error(`DIAGNOSTIC_ERROR_CAUSE: ${redact(err.cause.message || String(err.cause))}`);
    }
  } finally {
    if (client) {
      await client.close();
      console.log("DIAGNOSTIC_STEP: Client connection closed safely.");
    }
  }
}

runDiagnosis().catch((err) => {
  console.error("FATAL_DIAG_ERROR:", redact(err.message));
});

