import dotenv from "dotenv";
import path from "path";
import { fileURLToPath } from "url";
import { MongoClient } from "mongodb";
import { MongoInvestigationsRepository } from "../../server/src/repositories/mongoInvestigationsRepository.js";
import { COLLECTIONS, ensureIndexes } from "../../server/src/db/collections.js";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
dotenv.config({ path: path.resolve(__dirname, "../../server/.env") });

function redact(text: unknown): string {
  if (!text) return "";
  return String(text)
    .replace(/mongodb(\+srv)?:\/\/[^@]+@/gi, "mongodb+srv://<redacted>:<redacted>@")
    .replace(/:([^:@]+)@/g, ":<redacted>@");
}

async function verifyLiveAtlasPersistence() {
  const uri = process.env.MONGODB_URI;
  if (!uri) {
    console.error("ATLAS_LIVE_ERROR: MONGODB_URI not set in server/.env");
    process.exit(1);
  }

  const dbName = process.env.MONGODB_DB_NAME || "keys_departed";
  console.log(`[Atlas Live Verification] Connecting to Atlas database: '${dbName}'...`);

  // Client 1: Initial Backend Session
  const client1 = new MongoClient(uri, {
    serverSelectionTimeoutMS: 8000,
    connectTimeoutMS: 8000,
    appName: "keys-departed-live-test-session-1",
  });

  const testInvId = `inv_atlas_live_${Date.now()}`;
  const testOwner = "auth0|atlas_verified_engineer";

  try {
    await client1.connect();
    const db1 = client1.db(dbName);
    const pingRes = await db1.command({ ping: 1 });
    console.log(`[Atlas Live Verification] Ping Result: ${JSON.stringify(pingRes)}`);

    console.log("[Atlas Live Verification] Ensuring collections and indexes on Atlas...");
    await ensureIndexes(db1);

    const repo1 = new MongoInvestigationsRepository(db1);

    // Step 1: Create Investigation
    console.log(`[Atlas Live Verification] Step 1: Creating investigation '${testInvId}' on Atlas...`);
    const inv = await repo1.createInvestigation(
      {
        name: "Atlas Live Persistence Verification Audit",
        organization_id: "secops_live",
        description: "Testing end-to-end Atlas persistence across backend restarts",
      },
      testOwner,
    );
    console.log(`[Atlas Live Verification] Investigation Created: ID=${inv.investigation_id}, status=${inv.status}`);

    // Step 2, 3, 4: Upload, parse, store files and records
    console.log("[Atlas Live Verification] Step 2-4: Uploading evidence files and persisting records...");
    const uploadRes = await repo1.addUploadedFiles(inv.investigation_id, [
      {
        filename: "atlas_deploy.log",
        content:
          "commit 8f92ab01\nAuthor: Sarah Chen <schen@internal.corp>\nDeploy key acc_deploy_key_881 verified in Atlas cluster.",
      },
      {
        filename: "atlas_service.json",
        content: JSON.stringify([
          {
            record_id: `rec_${testInvId}_01`,
            type: "ticket",
            ts: new Date().toISOString(),
            author_handle: "schen",
            actor_account_id: "acc_service_runner_404",
            content: "TICKET-404: Service runner 404 authenticated against Atlas",
            structured: true,
          },
        ]),
      },
    ]);
    console.log(
      `[Atlas Live Verification] Upload Complete: files=${uploadRes.files.length}, records=${uploadRes.extracted_records.length}, status=${uploadRes.investigation.status}`,
    );

    // Step 5, 6, 7: Process investigation, store discovered identities and deterministic verification results
    console.log("[Atlas Live Verification] Step 5-7: Processing investigation and storing findings...");
    const findings = await repo1.processInvestigation(inv.investigation_id);
    console.log(
      `[Atlas Live Verification] Processing Complete: status=${findings.investigation.status}, discovered_accounts=${findings.discovered_accounts.length}, claims_verified=${findings.processing_summary.claims_verified_count}`,
    );

    // Step 8: Retrieve investigation before restart
    console.log("[Atlas Live Verification] Step 8: Retrieving investigation and findings from session 1...");
    const preRestartInv = await repo1.findInvestigationById(inv.investigation_id);
    const preRestartFindings = await repo1.getFindingsByInvestigationId(inv.investigation_id);
    console.log(`[Atlas Live Verification] Session 1 Verification: inv_status=${preRestartInv?.status}, findings_ok=${Boolean(preRestartFindings)}`);

    // Step 9: Disconnect Client 1 and simulate backend restart by instantiating Client 2
    console.log("\n[Atlas Live Verification] Step 9: Simulating backend restart (closing Client 1, opening Client 2)...");
    await client1.close();
    console.log("[Atlas Live Verification] Client 1 connection closed.");

    const client2 = new MongoClient(uri, {
      serverSelectionTimeoutMS: 8000,
      connectTimeoutMS: 8000,
      appName: "keys-departed-live-test-session-2",
    });
    await client2.connect();
    const db2 = client2.db(dbName);
    const repo2 = new MongoInvestigationsRepository(db2);
    console.log("[Atlas Live Verification] Client 2 connected (Backend restarted successfully).");

    // Step 10: Retrieve the exact same investigation and results again from restarted backend
    console.log("[Atlas Live Verification] Step 10: Retrieving persisted data from Atlas using Client 2...");
    const postRestartInv = await repo2.findInvestigationById(inv.investigation_id);
    const postRestartFindings = await repo2.getFindingsByInvestigationId(inv.investigation_id);
    const postRestartFiles = await repo2.findFilesByInvestigationId(inv.investigation_id);
    const postRestartList = await repo2.listInvestigations(testOwner, "false");

    console.log("--------------------------------------------------");
    console.log(`[Atlas Live Verification] Post-Restart Investigation ID: ${postRestartInv?.investigation_id}`);
    console.log(`[Atlas Live Verification] Post-Restart Status: ${postRestartInv?.status}`);
    console.log(`[Atlas Live Verification] Post-Restart File Count: ${postRestartInv?.file_count}`);
    console.log(`[Atlas Live Verification] Post-Restart Record Count: ${postRestartInv?.record_count}`);
    console.log(`[Atlas Live Verification] Post-Restart Files Retrieved: ${postRestartFiles.length}`);
    console.log(`[Atlas Live Verification] Post-Restart Discovered Accounts: ${postRestartFindings?.discovered_accounts.length}`);
    console.log(`[Atlas Live Verification] Post-Restart Claims Verified: ${postRestartFindings?.processing_summary.claims_verified_count}`);
    console.log(`[Atlas Live Verification] Post-Restart Owner Workspace List Count: ${postRestartList.length}`);
    console.log("--------------------------------------------------");

    if (
      postRestartInv &&
      postRestartInv.status === "completed" &&
      postRestartFindings &&
      postRestartFindings.discovered_accounts.length >= 2 &&
      postRestartList.length === 1
    ) {
      console.log("[Atlas Live Verification] FULL 10-STEP ATLAS PERSISTENCE LIFECYCLE VERIFIED: SUCCESS!");
    } else {
      throw new Error("Verification failed: Data integrity mismatch after restart.");
    }

    // Cleanup: Safely remove ONLY the test records created for this verification run
    console.log(`[Atlas Live Verification] Cleaning up test records for '${testInvId}'...`);
    await db2.collection(COLLECTIONS.INVESTIGATIONS).deleteOne({ investigation_id: inv.investigation_id });
    await db2.collection(COLLECTIONS.INVESTIGATION_FILES).deleteMany({ investigation_id: inv.investigation_id });
    await db2.collection(COLLECTIONS.INVESTIGATION_FINDINGS).deleteOne({ investigation_id: inv.investigation_id });
    await db2.collection(COLLECTIONS.RECORDS).deleteMany({ investigation_id: inv.investigation_id });
    console.log("[Atlas Live Verification] Test cleanup complete. No unrelated data touched.");

    await client2.close();
    console.log("[Atlas Live Verification] Client 2 connection closed safely.");
  } catch (err: unknown) {
    console.error("[Atlas Live Verification] Error:", redact(err));
    if (client1) await client1.close();
    process.exit(1);
  }
}

verifyLiveAtlasPersistence();

