  // Free-text log or txt file
  const chunks = content.split(/\n\s*\n/).filter((c) => c.trim().length > 0);
  chunks.forEach((chunk, idx) => {
    let type: EvidenceRecordType = "commit";
    if (/TICKET-[0-9]+/i.test(chunk)) {
