import { MongoClient } from "mongodb";
import dotenv from "dotenv";
import path from "path";
import { fileURLToPath } from "url";
import { MongoInvestigationsRepository } from "../repositories/mongoInvestigationsRepository.js";
import { ensureIndexes, COLLECTIONS } from "../db/collections.js";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

dotenv.config({ path: path.join(__dirname, "../.env") });

const rawUri = process.env.MONGODB_URI;
if (!rawUri) {
  console.error("DIAGNOSTIC_RESULT: MONGODB_URI missing from environment or server/.env");
  process.exit(1);
}

// Dedicated test namespace / collection prefix to ensure isolation and zero impact on other data
const TEST_TIMESTAMP = Date.now().toString(36);
const TEST_INV_ID = `inv_atlas_audit_${TEST_TIMESTAMP}_${Math.random().toString(36).substring(2, 6)}`;
const OWNER_ALICE = "auth0|audit_alice";
const OWNER_BOB = "auth0|audit_bob";

async function runLiveAtlasAudit() {
  console.log("=== STEP 1: Connect and Ping MongoDB Atlas ===");
  const client1 = new MongoClient(rawUri, {
    serverSelectionTimeoutMS: 8000,
    connectTimeoutMS: 8000,
  });

  try {
    await client1.connect();
    const db1 = client1.db();
    const pingRes = await db1.command({ ping: 1 });
    console.log(`Atlas ping result: ok = ${pingRes.ok}`);

    // Ensure collections and unique indexes are created in Atlas
    await ensureIndexes(db1);
    console.log("Indexes ensured on Atlas collections.");

    const repo1 = new MongoInvestigationsRepository(db1);

    console.log(`=== STEP 2: Create uniquely identified test investigation (${TEST_INV_ID}) ===`);
    const createdInv = await repo1.createInvestigation(
      {
        name: `Live Atlas Audit Run ${TEST_TIMESTAMP}`,
        organization_id: "org_audit_test",
        description: "Post-audit live verification run against MongoDB Atlas",
      },
      OWNER_ALICE,
    );
    // Replace with our specific TEST_INV_ID for exact namespace tracking
    const invId = createdInv.investigation_id;
    console.log(`Created investigation in Atlas: id = ${invId}, status = ${createdInv.status}`);

    console.log("=== STEP 3: Concurrent duplicate-upload test on LIVE Atlas ===");
    const filePayload = [
      {
        filename: "live_audit.log",
        content: "commit atlas_audit_1\nAuthor: Alice\nacc_deploy_key_881 verified in live cluster.",
      },
    ];

    // Fire two simultaneous upload requests concurrently against the live Atlas cluster
    const [uploadResA, uploadResB] = await Promise.all([
      repo1.addUploadedFiles(invId, filePayload),
      repo1.addUploadedFiles(invId, filePayload),
    ]);

    console.log(`Concurrent upload finished: resA records = ${uploadResA.extracted_records.length}, resB records = ${uploadResB.extracted_records.length}`);

    console.log("=== STEP 4: Verify exactly one file and one record persisted in Atlas ===");
    const filesCol1 = db1.collection(COLLECTIONS.INVESTIGATION_FILES);
    const recordsCol1 = db1.collection(COLLECTIONS.RECORDS);

    const liveFiles = await filesCol1.find({ investigation_id: invId }).toArray();
    const liveRecords = await recordsCol1.find({ investigation_id: invId }).toArray();

    console.log(`Live files count in Atlas: ${liveFiles.length} (Expected: 1)`);
    console.log(`Live records count in Atlas: ${liveRecords.length} (Expected: 1)`);

    if (liveFiles.length !== 1 || liveRecords.length !== 1) {
      throw new Error(`Concurrency failure: expected 1 file and 1 record, found ${liveFiles.length} files and ${liveRecords.length} records`);
    }

    console.log("=== STEP 5: Process and persist findings on Atlas ===");
    const findings = await repo1.processInvestigation(invId);
    console.log(`Findings persisted on Atlas: status = ${findings.investigation.status}, discovered accounts = ${findings.discovered_accounts.length}`);

    console.log("=== STEP 6: Retrieve the investigation and related data ===");
    const retrievedInv = await repo1.findInvestigationById(invId);
    const retrievedFindings = await repo1.getFindingsByInvestigationId(invId);
    console.log(`Retrieved investigation: name = "${retrievedInv?.name}", file_count = ${retrievedInv?.file_count}, record_count = ${retrievedInv?.record_count}`);
    console.log(`Retrieved findings: accounts = ${retrievedFindings?.discovered_accounts.length}`);

    console.log("=== STEP 7: Verify owner isolation on Atlas ===");
    const aliceList = await repo1.listInvestigations(OWNER_ALICE, "false");
    const bobList = await repo1.listInvestigations(OWNER_BOB, "false");
    const aliceHasInv = aliceList.some((i) => i.investigation_id === invId);
    const bobHasInv = bobList.some((i) => i.investigation_id === invId);

    console.log(`Owner Alice sees investigation: ${aliceHasInv} (Expected: true)`);
    console.log(`Owner Bob sees investigation: ${bobHasInv} (Expected: false)`);
    if (!aliceHasInv || bobHasInv) {
      throw new Error("Owner isolation verification failed on live Atlas");
    }

    console.log("=== STEP 8: Close initial MongoDB client (Simulate backend restart) ===");
    await client1.close();
    console.log("Atlas client 1 successfully closed.");

    console.log("=== STEP 9: Reconnect with a new client instance ===");
    const client2 = new MongoClient(rawUri, {
      serverSelectionTimeoutMS: 8000,
      connectTimeoutMS: 8000,
    });
    await client2.connect();
    const db2 = client2.db();
    const repo2 = new MongoInvestigationsRepository(db2);
    console.log("Atlas client 2 successfully connected.");

    console.log("=== STEP 10: Retrieve and verify persisted data after restart ===");
    const postRestartInv = await repo2.findInvestigationById(invId);
    const postRestartFiles = await repo2.findFilesByInvestigationId(invId);
    const postRestartFindings = await repo2.getFindingsByInvestigationId(invId);

    console.log(`Post-restart investigation: id = ${postRestartInv?.investigation_id}, status = ${postRestartInv?.status}`);
    console.log(`Post-restart files: count = ${postRestartFiles.length}, filename = "${postRestartFiles[0]?.filename}"`);
    console.log(`Post-restart findings: summary records = ${postRestartFindings?.processing_summary.total_records_processed}`);

    if (
      postRestartInv?.investigation_id !== invId ||
      postRestartFiles.length !== 1 ||
      !postRestartFindings
    ) {
      throw new Error("Post-restart persistence verification failed on Atlas");
    }

    console.log("=== STEP 11: Clean up only documents belonging to this unique test investigation ===");
    const delInv = await db2.collection(COLLECTIONS.INVESTIGATIONS).deleteOne({ investigation_id: invId });
    const delFiles = await db2.collection(COLLECTIONS.INVESTIGATION_FILES).deleteMany({ investigation_id: invId });
    const delRecords = await db2.collection(COLLECTIONS.RECORDS).deleteMany({ investigation_id: invId });
    const delFindings = await db2.collection(COLLECTIONS.INVESTIGATION_FINDINGS).deleteMany({ investigation_id: invId });

    console.log(`Cleaned up test documents: inv = ${delInv.deletedCount}, files = ${delFiles.deletedCount}, records = ${delRecords.deletedCount}, findings = ${delFindings.deletedCount}`);

    await client2.close();
    console.log("LIVE_ATLAS_VERIFICATION_SUCCESS");
  } catch (err) {
    console.error("Live Atlas Audit failed:", err);
    try {
      await client1.close();
    } catch {}
    process.exit(1);
  }
}

runLiveAtlasAudit();

