async function testOllama() {
  const url = "http://127.0.0.1:11434/api/generate";
  const body = {
    model: "gemma3:4b",
    prompt: "Respond with only a JSON object: {\"status\":\"ok\"}",
    stream: false,
    format: "json",
    options: {
      temperature: 0,
    },
  };

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 30000);

  try {
    const res = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
      signal: controller.signal,
    });
    clearTimeout(timeout);
    const data = await res.json();
    console.log("OLLAMA_RESPONSE:", JSON.stringify(data.response));
  } catch (err) {
    console.error("OLLAMA_ERROR:", err.message);
  }
}

testOllama();

async function pingOllama() {
  try {
    const res = await fetch("http://127.0.0.1:11434/api/tags");
    const json = await res.json();
    console.log("TAGS_SUCCESS:", json.models.map(m => m.name));
  } catch (err) {
    console.error("TAGS_ERR:", err.message);
  }
}
pingOllama();

