  describe("Persistence & Benchmark Evaluation (TABPFN-06 to TABPFN-08)", () => {
    it("TABPFN-06: Runs 3-way evaluation benchmark with zero data leakage", () => {
      const stdout = execSync("python python-tools/evaluate_prioritization.py", {
        encoding: "utf-8",
